#!/bin/bash
# determinism.sh <faust-A> <faust-B> [witnesses]
#
# The determinism gate : the same programs generated by two faust binaries built
# from the same commit (by two C++ compilers, or on two machines), compared byte
# to byte. Every witness is generated under eight option sets. The -I paths are
# relative, so that the compile_options the emitted code quotes are the same on
# both sides. Exit status 1 when any output differs. Given the same binary
# twice, it checks that one binary emits the same code from one run to the
# next : an order taken from heap addresses breaks that (the -sch set lists
# the dependencies of every task, the ocpp -omp set names the loops).
#
# A witness line may carry a fourth column, the options of that witness alone, for a backend
# that accepts few programs (sdf3, vhdl) or a graph written beside the code (-tg, -sg). It is
# generated by each side in a directory of its own, with -O . so that nothing is written beside
# the source, and the two directories are compared file by file.
set -u; export LC_ALL=C
HERE=$(cd "$(dirname "$0")" && pwd)
A=${1:?usage: determinism.sh <faust-A> <faust-B> [witnesses]}; B=${2:?usage: determinism.sh <faust-A> <faust-B> [witnesses]}
W=${3:-$HERE/witnesses.txt}
# absolute paths, resolved from the caller's directory, before moving to the witnesses' one
A=$(cd "$(dirname "$A")" && pwd)/$(basename "$A"); B=$(cd "$(dirname "$B")" && pwd)/$(basename "$B")
W=$(cd "$(dirname "$W")" && pwd)/$(basename "$W")
cd "$HERE"
OUT=$HERE/out; rm -rf "$OUT"; mkdir -p "$OUT/a" "$OUT/b"
INC="-I ../impulse-tests/dsp -I ../../libraries -I ../../libraries/dx7"
# the same, seen from out/{a,b}/<leg>.d, where the witnesses with their own options run
UP=../../..
LINC="-I $UP/../impulse-tests/dsp -I $UP/../../libraries -I $UP/../../libraries/dx7"
SETS=("-lang cpp -double -t 0" "-lang cpp -double -t 0 -vec" "-lang ocpp -double -t 0" "-lang ocpp -double -t 0 -vec"
      "-lang cpp -double -t 0 -ftz 2" "-lang ocpp -double -t 0 -fir" "-lang cpp -double -t 0 -sch"
      "-lang ocpp -double -t 0 -omp")
echo "A : $A"; "$A" --version | sed 's/^/    /'
echo "B : $B"; "$B" --version | sed 's/^/    /'
# the same binary on both sides : the two sides are two runs, and a difference comes from the run
if [ "$A" = "$B" ]; then SIDES="runs"; CAUSE="changes from one run of faust to the next"
else SIDES="binaries"; CAUSE="depends on how faust was built"; fi
n=0; same=0; diff=0; fail=0; bad=""; firsterr=""
while IFS=$'\t' read -r name file pn opts; do
    [ -z "$name" ] && continue; case "$name" in \#*) continue;; esac
    [ "$pn" = "-" ] && pn=""
    line=$(printf "%-28s" "$name")
    if [ -n "$opts" ]; then
        leg="$name.x.d"
        for k in a b; do
            bin=$A; [ $k = b ] && bin=$B
            mkdir -p "$OUT/$k/$leg"
            # shellcheck disable=SC2086
            if ! (cd "$OUT/$k/$leg" && "$bin" $opts $LINC ${pn:+-pn $pn} "$UP/$file" -O . -o out.txt) 2> "$OUT/$k/$name.x.err"; then
                : > "$OUT/$k/$leg.failed"; firsterr=${firsterr:-"$name [$opts] $k : $(head -1 "$OUT/$k/$name.x.err")"}
            fi
        done
        n=$((n+1))
        if [ -e "$OUT/a/$leg.failed" ] && [ -e "$OUT/b/$leg.failed" ]; then
            fail=$((fail+1)); line="$line  fail"
        elif [ -e "$OUT/a/$leg.failed" ] || [ -e "$OUT/b/$leg.failed" ] || ! diff -r "$OUT/a/$leg" "$OUT/b/$leg" > /dev/null; then
            diff=$((diff+1)); line="$line  DIFF"; bad="$bad$name [$opts]"$'\n'
        else
            same=$((same+1)); line="$line  same"
        fi
        echo "$line"
        continue
    fi
    for i in "${!SETS[@]}"; do
        OPT=${SETS[$i]}
        for k in a b; do
            bin=$A; [ $k = b ] && bin=$B
            # shellcheck disable=SC2086
            if ! "$bin" $OPT $INC ${pn:+-pn $pn} "$file" -o "$OUT/$k/$name.$i.cpp" 2> "$OUT/$k/$name.$i.err"; then
                echo FAUSTFAIL > "$OUT/$k/$name.$i.cpp"; firsterr=${firsterr:-"$name [$OPT] $k : $(head -1 "$OUT/$k/$name.$i.err")"}
            fi
        done
        n=$((n+1))
        if grep -q '^FAUSTFAIL$' "$OUT/a/$name.$i.cpp" "$OUT/b/$name.$i.cpp"; then
            fail=$((fail+1)); line="$line  fail"
        elif cmp -s "$OUT/a/$name.$i.cpp" "$OUT/b/$name.$i.cpp"; then
            same=$((same+1)); line="$line  same"
        else
            diff=$((diff+1)); line="$line  DIFF"; bad="$bad$name [$OPT]"$'\n'
        fi
    done
    echo "$line"
done < "$W"
echo
echo "option sets : ${SETS[*]/#/| }   (and the witnesses with a fourth column, each under its own)"
echo "generations : $n   identical : $same   different : $diff   failed on both sides : $fail"
if [ $diff -gt 0 ]; then
    echo; echo "DIFFERENT (the emitted code $CAUSE) :"; printf '%s' "$bad" | sed 's/^/    /'
    echo "the outputs are in $OUT/a and $OUT/b"
    exit 1
fi
if [ $same -eq 0 ] || [ $fail -gt 0 ]; then
    echo; echo "NOT A VERDICT : $fail generation(s) failed on both sides (a gate that cannot generate proves nothing)"
    [ -n "$firsterr" ] && echo "    first error : $firsterr"
    exit 2
fi
echo "OK : the emitted code is the same for both $SIDES"
